package e.e.a;
import android.preference.*;import android.text.*;import android.view.*;import android.widget.*;import java.util.*;
public final class SettingsTools {
 static PreferenceGroup parent(PreferenceGroup g,Preference p){for(int i=0;i<g.getPreferenceCount();i++){Preference x=g.getPreference(i);if(x==p)return g;if(x instanceof PreferenceGroup){PreferenceGroup r=parent((PreferenceGroup)x,p);if(r!=null)return r;}}return null;}
 public static void install(PreferenceActivity a){a.getListView().post(()->{if(a.isFinishing())return;PreferenceGroup root=a.getPreferenceScreen(),other=(PreferenceGroup)a.findPreference("nicoid_content_filter");if(other!=null){other.setTitle(PanelUi.tr(a,"その他","Other","其他"));NgCommentSettings.install(a,other);for(String key:new String[]{"search_suggestions_enabled","show_shorts_menu","video_info_follow_button"}){Preference p=a.findPreference(key);if(p!=null){PreferenceGroup old=parent(root,p);if(old!=null&&old!=other){old.removePreference(p);p.setOrder(other.getPreferenceCount());other.addPreference(p);}}}}ListView list=a.getListView();if(list.findViewWithTag("settings_search")!=null)return;LinearLayout header=new LinearLayout(a);header.setTag("settings_search");header.setPadding(PanelUi.dp(a,16),PanelUi.dp(a,8),PanelUi.dp(a,16),PanelUi.dp(a,8));LinearLayout pill=new LinearLayout(a);pill.setGravity(android.view.Gravity.CENTER_VERTICAL);pill.setPadding(PanelUi.dp(a,14),0,PanelUi.dp(a,8),0);pill.setBackground(PanelUi.round(a,ThemeChoice.isNight(a)?0xff303238:0xffeeeeee,28));header.addView(pill,new LinearLayout.LayoutParams(-1,PanelUi.dp(a,48)));View icon=new SearchIcon(a);pill.addView(icon,new LinearLayout.LayoutParams(PanelUi.dp(a,24),PanelUi.dp(a,24)));EditText search=new EditText(a);search.setSingleLine(true);search.setHint(PanelUi.tr(a,"設定項目を検索","Search settings","搜尋設定項目"));search.setTextColor(PanelUi.ink(a));search.setHintTextColor(ThemeChoice.isNight(a)?0xffbfc1c6:0xff67696d);search.setBackground(null);search.setPadding(PanelUi.dp(a,12),0,PanelUi.dp(a,8),0);search.setInputType(android.text.InputType.TYPE_CLASS_TEXT);pill.addView(search,new LinearLayout.LayoutParams(0,-1,1));list.setItemsCanFocus(true);list.addHeaderView(header,null,false);Node snapshot=new Node(root);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void onTextChanged(CharSequence s,int st,int before,int count){snapshot.restore(s.toString().trim().toLowerCase(Locale.ROOT),false);}public void afterTextChanged(Editable e){}});});}
 static final class SearchIcon extends View {final android.graphics.Paint p=new android.graphics.Paint(3);SearchIcon(android.content.Context c){super(c);setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);}protected void onDraw(android.graphics.Canvas c){c.save();float scale=Math.min(getWidth(),getHeight())/24f;c.scale(scale,scale);p.setColor(ThemeChoice.accent(getContext()));p.setStyle(android.graphics.Paint.Style.STROKE);p.setStrokeWidth(2);p.setStrokeCap(android.graphics.Paint.Cap.ROUND);c.drawCircle(10,10,6,p);c.drawLine(15,15,21,21,p);c.restore();}}
 static final class Node {final PreferenceGroup group;final ArrayList<Preference> entries=new ArrayList<>();final Map<Preference,Node> children=new HashMap<>();Node(PreferenceGroup g){group=g;for(int i=0;i<g.getPreferenceCount();i++){Preference p=g.getPreference(i);entries.add(p);if(p instanceof PreferenceGroup)children.put(p,new Node((PreferenceGroup)p));}}boolean restore(String q,boolean include){group.removeAll();for(Preference p:entries){boolean match=include||q.isEmpty()||String.valueOf(p.getTitle()).toLowerCase(Locale.ROOT).contains(q)||String.valueOf(p.getSummary()).toLowerCase(Locale.ROOT).contains(q);Node n=children.get(p);if(n!=null){if(n.restore(q,match))group.addPreference(p);}else if(match)group.addPreference(p);}return group.getPreferenceCount()>0;}}
}
